import { h, render } from 'preact';

import { TranslationsProvider } from '../components/translations';
import { CssProvider } from '../dom/css-registry';
import type { CardConfig, Hass } from '../types';
import { registerCustomElement } from '../utils/register';
import { Card } from './card';

export class CardRoot extends HTMLElement {
  protected _hass?: Hass;
  set hass(hass: Hass) {
    this._hass = hass;
  }
  setConfig(config: CardConfig): void {
    console.log('setConfig', config);
  }
  connectedCallback() {
    render(
      <CssProvider>
        <TranslationsProvider language={this._hass?.locale?.language ?? 'en'}>
          <Card />
        </TranslationsProvider>
      </CssProvider>,
      this,
    );
  }
  disconnectedCallback() {
    render(null, this);
  }
}

registerCustomElement('todo-plus-card', CardRoot);
